namespace UnityEngine {
 public struct Vector3 {public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}}
 public struct Quaternion {public float x,y,z;public static Quaternion Euler(float a,float b,float c){return new Quaternion{x=a,y=b,z=c};}}
 public class Transform {public Quaternion localRotation;public Vector3 localScale=new Vector3(1,1,1),localPosition;}
 public static class Mathf {public static float Clamp(float v,float a,float b){return Math.Max(a,Math.Min(b,v));}public static float Clamp01(float v){return Clamp(v,0,1);}public static float Max(float a,float b){return Math.Max(a,b);}public static float MoveTowards(float a,float b,float d){return Math.Abs(a-b)<=d?b:a+Math.Sign(b-a)*d;}}
 public static class Time {public static float deltaTime=.02f,fixedDeltaTime=.02f;}
}
public class KSPField:Attribute {public bool isPersistant,guiActive,guiActiveEditor;public string guiName;}
public class UI_FloatRange:Attribute {public float minValue,maxValue,stepIncrement;}
public class KSPEvent:Attribute {public bool guiActive,guiActiveEditor;public string guiName;}
public class KSPAction:Attribute {public KSPAction(string s){}}
public class KSPActionParam {}public class ConfigNode {}public enum StartState {Editor,Flight}
public class PartModule {public Part part;public Vessel vessel{get{return part==null?null:part.vessel;}}public virtual void OnLoad(ConfigNode n){}public virtual void OnStart(StartState s){}public virtual string GetInfo(){return "";}}
public class Part {public Vessel vessel=new Vessel();public System.Collections.Generic.List<object> protoModuleCrew=new System.Collections.Generic.List<object>();public System.Collections.Generic.Dictionary<string,UnityEngine.Transform> models=new System.Collections.Generic.Dictionary<string,UnityEngine.Transform>();public double charge=900;public int requests;public UnityEngine.Vector3 position=new UnityEngine.Vector3(4,5,6);public UnityEngine.Transform FindModelTransform(string n){return models.ContainsKey(n)?models[n]:null;}public double RequestResource(string n,double amount){if(n!="ElectricCharge")throw new Exception("unexpected resource");requests++;double v=Math.Min(charge,amount);charge-=v;return v;}}
public class Vessel {public enum Situations {ORBITING,SUB_ORBITAL,ESCAPING,LANDED,SPLASHED,FLYING,PRELAUNCH}public Situations situation=Situations.ORBITING;public bool loaded=true,packed;}
public static class HighLogic {public static bool LoadedSceneIsEditor,LoadedSceneIsFlight=true;}
public static class TimeWarp {public static int CurrentRateIndex;}
public static class GravityRingTest {
 static int checks;static void Check(bool c,string m){checks++;if(!c)throw new Exception(m);}static void Near(float a,float b,string m){Check(Math.Abs(a-b)<.002,m+" "+a+"/"+b);}
 static ModuleRWGravityRing Ring(){var p=new Part();p.models["RW_GravityRotor"]=new UnityEngine.Transform();for(int i=0;i<8;i++){p.models["RW_GravityHinge"+i.ToString("00")]=new UnityEngine.Transform();p.models["RW_GravityPod"+i.ToString("00")]=new UnityEngine.Transform();p.models["RW_GravityTelescopic"+i.ToString("00")]=new UnityEngine.Transform();}var m=new ModuleRWGravityRing{part=p};m.OnLoad(new ConfigNode());m.OnStart(StartState.Flight);return m;}
 static void Tick(ModuleRWGravityRing m,int n=2000){for(int i=0;i<n;i++)if(HighLogic.LoadedSceneIsEditor)m.Update();else m.FixedUpdate();}
 public static void Run(){
 var m=Ring();m.StartRing();Check(!m.running&&m.status.Contains("deploy"),"spin needs full deployment");m.Deploy();Tick(m);Near(m.deployment,1,"deploy completed");
 for(int i=0;i<8;i++){Near(m.part.models["RW_GravityHinge"+i.ToString("00")].localRotation.z,0,"spoke deployed");Near(m.part.models["RW_GravityPod"+i.ToString("00")].localScale.x,1,"inflated sector");Near(m.part.models["RW_GravityPod"+i.ToString("00")].localPosition.x,2.75f,"full spoke reach");Near(m.part.models["RW_GravityTelescopic"+i.ToString("00")].localScale.x,1,"full telescopic reach");}
 m.StartRing();Tick(m,500);Near(m.actualRpm,6,"rotation ramps to setpoint");Check(m.phase>0&&m.phase<360,"phase wraps");Check(m.acceleration.StartsWith("0.17 g"),"6 rpm at 4.2 m equivalent acceleration");
 m.Fold();Check(m.targetDeployment==1&&m.status.Contains("Stop"),"fold blocked while rotating");m.StopRing();Tick(m,500);Near(m.actualRpm,0,"spin down");m.part.protoModuleCrew.Add(new object());m.Fold();Check(m.targetDeployment==1&&m.status.Contains("crew"),"fold blocked when crewed");m.part.protoModuleCrew.Clear();m.Fold();Tick(m);Near(m.deployment,0,"fold completed");
 for(int i=0;i<8;i++){Near(m.part.models["RW_GravityHinge"+i.ToString("00")].localRotation.z,i%2==0?(i==0||i==4?82:88):-88,"alternating folded spokes");Near(m.part.models["RW_GravityPod"+i.ToString("00")].localScale.x,.5f,"fuller packed sectors");Near(m.part.models["RW_GravityPod"+i.ToString("00")].localScale.y,.85f,"pack height retained");Near(m.part.models["RW_GravityPod"+i.ToString("00")].localScale.z,.7f,"pack width retained");Near(m.part.models["RW_GravityPod"+i.ToString("00")].localPosition.x,.95f,"short stowed reach");Near(m.part.models["RW_GravityHinge"+i.ToString("00")].localPosition.x,1.72f,"packs close to hub");Near(m.part.models["RW_GravityTelescopic"+i.ToString("00")].localScale.x,.95f/2.75f,"stowed telescope length");}
 Near(m.part.position.x,4,"fixed hub x");Near(m.part.position.y,5,"fixed hub y");Near(m.part.position.z,6,"fixed hub z");Check(m.part.charge<900&&m.part.requests>0,"power consumed");
 foreach(var situation in new[]{Vessel.Situations.LANDED,Vessel.Situations.SPLASHED,Vessel.Situations.FLYING,Vessel.Situations.PRELAUNCH}){var ground=Ring();ground.vessel.situation=situation;ground.Deploy();Tick(ground);Near(ground.deployment,0,"unsafe deployment blocked");}
 var empty=Ring();empty.part.charge=0;empty.Deploy();Tick(empty);Near(empty.deployment,0,"no-power deployment paused");Check(empty.status.Contains("charge"),"no power status");empty.part.charge=900;Tick(empty);Near(empty.deployment,1,"deployment resumes with power");empty.StartRing();Tick(empty,500);empty.part.charge=0;Tick(empty,500);Near(empty.actualRpm,0,"coasts down without power");empty.part.charge=900;Tick(empty,500);Near(empty.actualRpm,6,"spin resumes with power");
 var captured=Ring();captured.deployment=1;captured.targetDeployment=1;captured.actualRpm=4;captured.phase=123;captured.running=true;captured.OnLoad(new ConfigNode());Near(captured.phase,123,"saved phase restored");Near(captured.actualRpm,4,"saved speed restored");Near(captured.part.models["RW_GravityRotor"].localRotation.y,123,"restored visual pose");
 foreach(string gate in new[]{"packed","unloaded","warp"}){var pause=Ring();pause.Deploy();if(gate=="packed")pause.vessel.packed=true;if(gate=="unloaded")pause.vessel.loaded=false;if(gate=="warp")TimeWarp.CurrentRateIndex=1;Tick(pause);Near(pause.deployment,0,"pause "+gate);Check(pause.part.requests==0,"no background power "+gate);TimeWarp.CurrentRateIndex=0;}
 HighLogic.LoadedSceneIsEditor=true;HighLogic.LoadedSceneIsFlight=false;var editor=Ring();editor.vessel.situation=Vessel.Situations.PRELAUNCH;editor.Deploy();Tick(editor);editor.StartRing();Tick(editor,500);Near(editor.actualRpm,6,"editor rotation preview");Near((float)editor.part.charge,900,"editor no power draw");editor.StopRing();Tick(editor,500);editor.Fold();Tick(editor);Near(editor.deployment,0,"editor fold preview");
 foreach(float bad in new[]{float.NaN,float.PositiveInfinity,-100f,1000f}){var invalid=Ring();invalid.deployment=bad;invalid.rpm=bad;invalid.phase=bad;invalid.actualRpm=bad;invalid.OnLoad(new ConfigNode());Check(invalid.deployment>=0&&invalid.deployment<=1&&invalid.rpm>=1&&invalid.rpm<=8,"invalid persistent state normalized");}
 var stages=Ring();for(int i=0;i<=100;i++){stages.deployment=stages.targetDeployment=i/100f;stages.OnLoad(new ConfigNode());foreach(var tr in stages.part.models.Values)Check(!float.IsNaN(tr.localScale.x)&&!float.IsNaN(tr.localRotation.z),"finite intermediate transforms");}
 new ModuleRWGravityRing().OnLoad(new ConfigNode());Check(true,"missing model safe");
 Console.WriteLine("PASS "+checks+" gravity-ring assertions: deployment/folding, spin gates/ramp, saved phase, power, crew interlocks, orbit/editor/warp, fixed hub and finite intermediate poses");}
}
